from pathlib import Path
import json

# Cada ficha desarrolla el argumento de un capítulo con una práctica propia.
SPECS={
1: dict(title='Soledad con propósito: construir un espacio propio',purpose='Usar un tiempo a solas para revisar prioridades y producir un resultado concreto.',deepening=['La soledad del capítulo representa un lugar de examen personal. Su utilidad aparece cuando puedes señalar qué hiciste allí: ordenar una decisión, estudiar una dificultad o terminar una tarea. Separarte temporalmente del ruido te permite reconocer cuánto de tu agenda elegiste y cuánto aceptaste por inercia.','Conviene dar a ese espacio un comienzo, una actividad y una salida. Una retirada indefinida puede dejar los mismos asuntos pendientes. El criterio de avance es volver con mayor claridad y cumplir mejor tus compromisos. La autonomía también admite vínculos que respetan tu tiempo y contribuyen a tu vida.'],method=[['Preparar el espacio','Reserva treinta minutos, elimina notificaciones y lleva una única pregunta por resolver.'],['Encontrar la prioridad','Anota tus pendientes y elige el que más influye en tu semana. Explica por qué.'],['Regresar con una decisión','Define una acción, una fecha y la persona a quien debes comunicarla.']],case='Un estudiante acepta reuniones diarias y posterga un proyecto. Dedica una tarde a revisar fechas, descubre que necesita tres bloques de estudio y los reserva. Informa a sus compañeros cuándo estará disponible. Su soledad produce una agenda ejecutable y una forma clara de participar en el grupo.',opportunities=[['Estudio','Crear bloques de concentración con una tarea verificable.'],['Organización','Elegir compromisos que realmente puedes sostener.'],['Relaciones','Comunicar disponibilidad sin buscar aprobación constante.']],exercise=['Mapa de prioridades','Divide una hoja en obligaciones, elecciones y distracciones. Elige una modificación en cada columna.'],plan=['Registrar interrupciones','Elegir una pregunta','Preparar el espacio','Trabajar treinta minutos','Comunicar un límite de tiempo','Terminar la tarea elegida','Revisar claridad y compromisos'],questions=['¿Qué resolví durante el tiempo a solas?','¿Qué compromiso atendí mejor al regresar?','¿Cuándo volveré a revisar mis prioridades?'],principle='La soledad construye cuando deja una decisión que puedes llevar al mundo.'),
2: dict(title='Retirarse con claridad y responsabilidad',purpose='Reducir disponibilidad sin dejar compromisos importantes en una zona ambigua.',deepening=['El capítulo vincula la retirada con recuperar dirección. Para aplicarlo, identifica de qué quieres apartarte: una conversación repetitiva, una actividad que aceptaste por costumbre o una relación que ya decidiste terminar. Cada situación tiene responsabilidades distintas.','Una pausa puede comunicarse en una frase breve. Si hay trabajo compartido, dinero, cuidados o acuerdos pendientes, enuméralos y establece cómo cerrarás tu participación. La firmeza se vuelve más comprensible cuando tu conducta coincide con lo que has comunicado. No necesitas convertir cada límite en un debate interminable.'],method=[['Definir el alcance','Especifica si necesitas horas de descanso, menor frecuencia de contacto o una separación definitiva.'],['Resolver lo pendiente','Identifica entregas, devoluciones y compromisos que dependen de ti.'],['Comunicar una vez','Expresa decisión y disponibilidad con precisión; evita mensajes contradictorios posteriores.']],case='Un profesional sale de un grupo que ocupa todas sus noches. Comunica que dejará de participar desde el viernes, entrega el documento que tenía asignado y silencia las notificaciones. Así libera tiempo y deja a los demás información suficiente para reorganizarse.',opportunities=[['Tiempo','Recuperar horarios definidos para tus prioridades.'],['Comunicación','Aprender a expresar límites en pocas frases.'],['Confiabilidad','Cerrar tareas antes de abandonar un proyecto.']],exercise=['Una salida en tres líneas','Escribe qué decides, qué asunto resolverás y desde cuándo cambia tu disponibilidad.'],plan=['Identificar el desgaste','Definir el alcance de la pausa','Listar compromisos','Preparar el mensaje','Resolver un pendiente','Aplicar la disponibilidad acordada','Evaluar el tiempo recuperado'],questions=['¿Estoy tomando distancia o buscando provocar una reacción?','¿Qué responsabilidad continúa siendo mía?','¿Mi conducta hace comprensible mi decisión?'],principle='Una salida clara libera energía y reduce asuntos pendientes.'),
3: dict(title='Valor propio: convertir la singularidad en contribución',purpose='Construir una forma de trabajar reconocible por su calidad y consistencia.',deepening=['La idea de ser imposible de reemplazar expresa el deseo de tener una identidad sólida. En la práctica, puedes desarrollar una combinación de habilidades, criterio y cumplimiento que haga valiosa tu participación. Esa combinación se demuestra en problemas resueltos y trabajos terminados.','Tu valor personal no depende de ocupar una posición exclusiva. Trabajar bien incluye compartir conocimiento y permitir que otros continúen una tarea. Busca una excelencia que fortalezca tu autonomía y al equipo: aprender, documentar y cumplir ofrece una base más estable que intentar controlar la dependencia de los demás.'],method=[['Elegir una competencia','Identifica una habilidad que puedas mejorar y una necesidad real donde aplicarla.'],['Demostrarla','Produce una muestra de trabajo con criterios de calidad definidos antes de comenzar.'],['Volverla consistente','Repite el proceso y documenta los pasos que hacen fiable tu resultado.']],case='Un integrante de un equipo prepara siempre sus informes a tiempo. Añade datos comprobados, explica sus decisiones y deja un archivo ordenado. Con el tiempo se vuelve una referencia porque los demás pueden confiar en su trabajo y aprender de su método.',opportunities=[['Aprendizaje','Profundizar una habilidad en lugar de acumular títulos sin práctica.'],['Trabajo','Entregar resultados que resuelvan una necesidad.'],['Legado','Dejar procedimientos útiles para otras personas.']],exercise=['Tu contribución en una frase','Completa: ayudo a resolver este problema mediante esta habilidad y demostraré mi avance con este resultado.'],plan=['Elegir la habilidad','Definir un problema real','Reunir herramientas','Crear una primera muestra','Solicitar una revisión concreta','Corregir el resultado','Documentar tu método'],questions=['¿Qué problema resuelve mi trabajo?','¿Qué mejora concreta puedo demostrar?','¿Alguien más puede usar lo que aprendí?'],principle='Una identidad sólida gana profundidad cuando se convierte en una contribución útil.'),
4: dict(title='Cerrar un vínculo sin actuar desde el impulso',purpose='Tomar y ejecutar una decisión de cierre basada en hechos y límites definidos.',deepening=['El corte frío del capítulo puede examinarse como una decisión tomada después de observar un patrón. Identifica hechos repetidos, acuerdos incumplidos y efectos en tu vida. Una decisión clara requiere distinguir esos hechos de una sospecha o de una discusión puntual.','El cierre también tiene una dimensión práctica: objetos, tareas, contacto y responsabilidades. Define cómo resolver cada asunto. Si tu decisión es definitiva, la coherencia consiste en sostenerla sin mensajes destinados a reabrir la negociación o provocar una respuesta. Las imágenes quirúrgicas de la obra expresan su tono literario.'],method=[['Revisar el patrón','Escribe tres hechos y las conversaciones previas sobre ellos.'],['Fijar la decisión','Elige entre renegociar un acuerdo, tomar distancia o terminar tu participación.'],['Organizar el cierre','Determina devoluciones, comunicaciones y límites posteriores.']],case='Dos socios repiten desacuerdos sobre entregas. Uno revisa el registro, confirma incumplimientos reiterados y decide retirarse. Deja un inventario, entrega sus archivos y acuerda una fecha de cierre. La separación queda definida por actos concretos.',opportunities=[['Criterio','Diferenciar un patrón de un conflicto aislado.'],['Orden','Reducir asuntos prácticos que mantienen abierto el vínculo.'],['Autonomía','Sostener decisiones sin buscar una reacción ajena.']],exercise=['Registro de decisión','Escribe hechos, impacto, alternativas consideradas y pasos de cierre. Revisa si tu conclusión sigue siendo la misma después de una pausa.'],plan=['Registrar los hechos','Revisar acuerdos previos','Considerar alternativas','Elegir la decisión','Organizar devoluciones','Comunicar el cierre','Comprobar asuntos resueltos'],questions=['¿Qué hechos sustentan mi decisión?','¿Qué asunto práctico falta cerrar?','¿Estoy sosteniendo el límite o prolongando el conflicto?'],principle='La firmeza se reconoce en una decisión clara y en un cierre ordenado.'),
5: dict(title='Una rutina que funciona cuando cambia el día',purpose='Diseñar hábitos sostenibles alrededor de prioridades y restricciones reales.',deepening=['El capítulo presenta la rutina como una arquitectura de dirección. Sus bloques deben tener una función: aprender, producir, cuidar recursos o preparar el siguiente día. Un horario lleno puede dar sensación de control y aun así dejar pendiente lo decisivo.','Define una versión habitual y una versión mínima para los días difíciles. Esta segunda versión mantiene la continuidad sin exigir circunstancias perfectas. Incluye descanso y margen para obligaciones imprevistas. Revisar una rutina permite mejorar su diseño cuando el contexto cambia.'],method=[['Elegir tres anclas','Selecciona actividades esenciales y fija una señal de inicio para cada una.'],['Preparar una versión mínima','Reduce cada actividad a un paso que todavía tenga valor en un día complicado.'],['Revisar la ejecución','Registra cumplimiento y obstáculos; cambia una condición por vez.']],case='Un estudiante planea leer dos horas diarias, pero sus turnos varían. Establece cuarenta minutos al despertar y una versión mínima de quince minutos. Prepara el material la noche anterior. Después de una semana descubre que la preparación facilita más la continuidad que aumentar la exigencia.',opportunities=[['Constancia','Repetir acciones pequeñas con resultados acumulables.'],['Entorno','Preparar materiales antes de necesitar fuerza de voluntad.'],['Revisión','Ajustar horarios usando lo que realmente ocurre.']],exercise=['Rutina de dos versiones','Escribe tres actividades, su señal de inicio y su versión mínima. Prueba el diseño durante una semana.'],plan=['Registrar el uso del tiempo','Elegir tres anclas','Preparar materiales','Probar la rutina habitual','Probar una versión mínima','Ajustar un obstáculo','Revisar continuidad y resultados'],questions=['¿Qué actividad sostiene mi prioridad principal?','¿Qué haré cuando disponga de menos tiempo?','¿Qué cambio del entorno facilitaría el cumplimiento?'],principle='Una rutina adquiere fuerza cuando puedes repetirla y revisarla.'),
6: dict(title='Principios estables y métodos revisables',purpose='Distinguir los valores que orientan tu vida de las estrategias que necesitan ajustes.',deepening=['El núcleo de la obra representa aquello que permanece cuando cambia el entorno. Para definirlo, formula principios que puedas aplicar a decisiones concretas: cumplir acuerdos, respetar límites, trabajar con honestidad o sostener una prioridad. Una lista de palabras solemnes necesita ejemplos para volverse operativa.','La estabilidad del criterio puede convivir con cambiar de opinión al conocer nuevos hechos. Un principio guía la evaluación; un método es una herramienta para realizarlo. Aferrarte a un método que dejó de funcionar puede alejarte de la finalidad que intentabas proteger.'],method=[['Nombrar el principio','Escribe una regla y un ejemplo donde resulte difícil cumplirla.'],['Separar medios y fines','Identifica qué quieres conservar y qué procedimiento puedes cambiar.'],['Definir excepciones','Aclara límites y situaciones que necesitan una revisión deliberada.']],case='Una persona valora la confiabilidad y acostumbra resolver todo sola. Cuando aumenta su carga, aprende a delegar y establece controles de entrega. Cambia su método para continuar cumpliendo el principio que considera central.',opportunities=[['Decisiones','Usar valores explícitos al elegir entre opciones.'],['Aprendizaje','Aceptar nueva información sin perder dirección.'],['Coherencia','Revisar si tu método sirve a tu propósito.']],exercise=['Principio, método y prueba','Elige un valor, identifica el método actual y propone otra forma de realizarlo. Decide cómo compararás los resultados.'],plan=['Listar valores centrales','Escribir ejemplos difíciles','Identificar un método rígido','Proponer una alternativa','Probarla en una tarea','Comparar los resultados','Actualizar tu criterio práctico'],questions=['¿Qué quiero preservar exactamente?','¿Este método todavía sirve a mi finalidad?','¿Qué información justificaría una revisión?'],principle='Un núcleo claro orienta el cambio y permite aprender sin perder dirección.'),
7: dict(title='Cerrar una etapa sin quedar atado a ella',purpose='Separar reconciliación, contacto y cierre personal para tomar una decisión propia.',deepening=['La amputación funciona en el capítulo como una imagen de separación definitiva. En el ámbito personal, el cierre puede consistir en terminar el contacto y atender las consecuencias de lo ocurrido. No exige resolver en un solo momento todas las emociones ni esperar que la otra persona acepte tu versión.','Perdonar, reconciliarse y volver a participar son decisiones diferentes. Puedes reconocer el daño, conservar un límite y seguir con tu vida. Es útil identificar lo que continúa abierto: un asunto material, una conversación repetida o la expectativa de recibir una explicación satisfactoria.'],method=[['Nombrar lo terminado','Especifica qué participación no vas a retomar.'],['Resolver lo resoluble','Organiza los asuntos materiales o compromisos todavía pendientes.'],['Construir continuidad','Reserva tiempo para actividades que sostengan la nueva etapa.']],case='Tras una colaboración fallida, alguien espera durante meses una disculpa para volver a trabajar. Decide cerrar sus pendientes documentales y comenzar un proyecto pequeño. La explicación que deseaba puede seguir faltando, pero su agenda vuelve a tener dirección propia.',opportunities=[['Claridad','Distinguir el cierre de la aprobación de la otra persona.'],['Organización','Completar asuntos concretos de la etapa anterior.'],['Continuidad','Crear una primera experiencia nueva y terminable.']],exercise=['Dos listas de cierre','Anota lo que depende de ti y lo que depende de otros. Actúa sobre un pendiente de la primera lista.'],plan=['Definir la etapa concluida','Separar responsabilidades','Identificar un pendiente','Resolverlo','Elegir una actividad nueva','Realizar su primer paso','Revisar el límite establecido'],questions=['¿Qué estoy esperando que otra persona haga?','¿Qué puedo cerrar por mi cuenta?','¿Qué actividad expresa mi siguiente etapa?'],principle='Puedes continuar tu vida aunque una historia no termine con la respuesta que esperabas.'),
8: dict(title='Reconocer pequeños desgastes y corregir acuerdos',purpose='Identificar patrones repetidos de cesión que alejan tu conducta de tus necesidades.',deepening=['El capítulo usa microfracturas para representar el efecto acumulado de pequeñas renuncias. Esta lectura editorial se centra en situaciones observables: decir sí sin revisar tu tiempo, aceptar bromas que te incomodan o aplazar una petición por miedo al desacuerdo. Registrar ejemplos permite reconocer patrones.','La metáfora no establece un diagnóstico de trauma. Examina la frecuencia, el contexto y la respuesta que eliges. Un ajuste útil puede ser comunicar antes una necesidad o cambiar un acuerdo. La evaluación se hace sobre conductas concretas y no sobre una etiqueta que defina toda tu identidad.'],method=[['Registrar una semana','Anota situación, respuesta e impacto cuando cedes algo importante.'],['Buscar el patrón','Identifica qué temor o expectativa se repite antes de responder.'],['Ensayar otra respuesta','Prepara una frase breve y úsala en una situación manejable.']],case='Alguien acepta tareas adicionales todos los viernes y pierde su tiempo de estudio. Durante una semana registra las peticiones y descubre que responde antes de mirar su agenda. Comienza a decir que confirmará disponibilidad en diez minutos y propone fechas que puede cumplir.',opportunities=[['Observación','Reconocer hábitos que pasan inadvertidos.'],['Límites','Pedir tiempo antes de comprometerte.'],['Acuerdos','Negociar cargas y plazos con datos concretos.']],exercise=['Registro de una cesión','Describe un episodio sin adjetivos globales: qué te pidieron, qué respondiste, qué necesitabas y qué podrías decir.'],plan=['Registrar un episodio','Registrar otro contexto','Encontrar la repetición','Preparar una frase','Ensayarla en voz alta','Aplicarla en una petición','Revisar el efecto del cambio'],questions=['¿Qué necesidad no expresé?','¿Qué temía que ocurriera si disentía?','¿Qué respuesta sería clara y proporcionada?'],principle='Un patrón empieza a cambiar cuando reconoces la situación y eliges otra respuesta.'),
9: dict(title='Hablar con precisión y sostener lo que dices',purpose='Mejorar la claridad de tus mensajes sin convertir la conversación en imposición.',deepening=['El lenguaje del capítulo se entiende como una herramienta para dar forma a decisiones. Hablar con precisión consiste en expresar qué observaste, qué propones y qué necesitas acordar. La firmeza se apoya en un mensaje comprensible y en la capacidad de sostenerlo con acciones.','Una pregunta, una disculpa o una expresión de incertidumbre pueden ser exactas y pertinentes. Elegir palabras requiere considerar lo que sabes y lo que aún necesitas verificar. La escucha permite ajustar un acuerdo; evita que una frase contundente tape información necesaria para decidir bien.'],method=[['Definir el mensaje','Resume en una frase el asunto que quieres resolver.'],['Aportar información','Incluye un hecho y una petición que la otra persona pueda entender.'],['Comprobar el acuerdo','Pregunta qué se entendió y deja claros responsable y fecha.']],case='En lugar de reclamar que nadie ayuda, un coordinador explica que faltan dos apartados del informe y pide confirmación de responsables antes de las seis. Escucha las limitaciones del equipo y fija nuevas entregas. La precisión permite pasar de la tensión a un acuerdo verificable.',opportunities=[['Claridad','Reducir rodeos cuando solicitas una acción.'],['Honestidad','Expresar incertidumbre cuando no conoces un dato.'],['Seguimiento','Vincular palabras con responsables y plazos.']],exercise=['Reescribir un mensaje','Transforma una queja general en observación, petición y fecha. Léela y elimina palabras que no aporten información.'],plan=['Elegir un mensaje difícil','Separar hechos y juicios','Escribir una petición','Añadir una fecha razonable','Ensayar la conversación','Comprobar lo entendido','Revisar el acuerdo alcanzado'],questions=['¿Qué necesita saber la otra persona?','¿Mi petición admite una respuesta clara?','¿He confirmado el acuerdo o solo he pronunciado una frase?'],principle='La palabra gana peso cuando informa, permite acordar y se respalda con conducta.'),
10: dict(title='Reducir estímulos para recuperar atención',purpose='Modificar el entorno que interrumpe tus tareas sin abandonar tu red de apoyo.',deepening=['La desintoxicación del entorno puede leerse como una revisión de estímulos y compromisos. Identifica qué interrupciones consumen tu atención y en qué momento aparecen. Una intervención pequeña sobre el entorno suele ser más fácil de ejecutar que intentar controlar todas tus reacciones a la vez.','Las imágenes de inflamación y mantenimiento son recursos expresivos del ensayo. El trabajo práctico de este apartado consiste en organizar notificaciones, horarios y espacios. La retirada tiene una finalidad y una duración; conserva los canales necesarios para obligaciones y relaciones que quieres cuidar.'],method=[['Medir las interrupciones','Cuenta cuándo cambias de tarea y qué desencadena el cambio.'],['Retirar un estímulo','Silencia una aplicación o aparta el teléfono durante un bloque definido.'],['Planear el regreso','Revisa mensajes en una franja acordada y responde los asuntos necesarios.']],case='Una persona mira el teléfono cada pocos minutos mientras prepara una entrega. Lo deja en otra habitación durante cuarenta minutos y avisa dónde pueden contactarla por un asunto urgente. Al terminar revisa mensajes y registra cuánta tarea avanzó.',opportunities=[['Concentración','Crear periodos de trabajo continuado.'],['Disponibilidad','Establecer franjas de respuesta previsibles.'],['Entorno','Reducir un estímulo que interrumpe de manera repetida.']],exercise=['Auditoría de interrupciones','Registra un bloque habitual y otro con una modificación del entorno. Compara tareas terminadas y cambios de atención.'],plan=['Contar interrupciones','Elegir un estímulo','Definir un bloque protegido','Preparar canales necesarios','Probar el nuevo entorno','Repetir la prueba','Comparar resultados y ajustar'],questions=['¿Qué estímulo produce más cambios de tarea?','¿Qué canal necesito conservar?','¿La reducción de ruido mejoró un resultado concreto?'],principle='Un entorno preparado facilita que tu atención permanezca donde decidiste.'),
11: dict(title='Dignidad: expresar límites y reconocer tu responsabilidad',purpose='Traducir el respeto propio en conductas claras y recíprocas.',deepening=['La dignidad del capítulo se relaciona con lo que aceptas y con cómo participas. Para convertirla en una práctica, identifica una situación donde tu conducta contradice un valor propio. Puede tratarse de un compromiso que aceptas por miedo, una descalificación repetida o una petición que no expresas.','Escuchar, disculparse por un error o pedir ayuda puede ser coherente con el respeto propio. La revisión consiste en observar si eliges esas acciones conscientemente o si renuncias a tus necesidades de manera habitual. Aplica a otras personas el mismo respeto que deseas recibir.'],method=[['Definir un límite','Describe la conducta concreta que necesitas cambiar en una interacción.'],['Expresarlo con reciprocidad','Comunica lo que puedes ofrecer y lo que no puedes aceptar.'],['Sostenerlo','Cumple tu decisión y revisa también tu propia conducta.']],case='En un equipo, las críticas se convierten en burlas. Un integrante pide que las observaciones se hagan sobre el trabajo, propone una revisión con criterios y se compromete a usar ese mismo trato. Su límite cambia la forma de participar y admite evaluar resultados.',opportunities=[['Respeto propio','Decidir sobre tu participación de forma consciente.'],['Reciprocidad','Pedir un trato que también puedas ofrecer.'],['Responsabilidad','Reconocer errores sin renunciar a tus límites.']],exercise=['Un límite recíproco','Escribe qué trato pides, qué conducta ofrecerás y cómo actuarás si el acuerdo no se cumple.'],plan=['Describir una situación','Reconocer tu necesidad','Examinar tu conducta','Escribir el límite','Comunicarlo','Sostener el acuerdo','Revisar reciprocidad y resultados'],questions=['¿Mi límite se refiere a una conducta concreta?','¿Ofrezco el mismo trato que solicito?','¿Qué parte de la situación me corresponde corregir?'],principle='La dignidad se sostiene con límites claros y responsabilidad por tus actos.'),
12: dict(title='Intimidad elegida: compatibilidad, acuerdos y cuidado',purpose='Decidir sobre vínculos íntimos desde tus valores y acuerdos mutuos.',deepening=['El capítulo plantea que la intimidad merece una decisión deliberada. Este desarrollo examina expectativas, tiempo disponible y compatibilidad entre personas. Pregúntate qué relación deseas, qué puedes ofrecer y si la otra persona busca algo compatible. Esos asuntos requieren conversación y libertad de elección.','Las comparaciones con trasplantes y sistemas eléctricos pertenecen al lenguaje del ensayo; no prueban que una persona produzca daño biológico en otra. La práctica propuesta se apoya en consentimiento, privacidad y acuerdos explícitos. Cualquier participante puede expresar un límite o cambiar de decisión.'],method=[['Aclarar expectativas','Define el tipo de vínculo que deseas y lo que puedes sostener.'],['Conversar los acuerdos','Habla de límites, privacidad y expectativas sin asumir que coinciden.'],['Revisar compatibilidad','Observa si las decisiones y conductas de ambos respetan lo acordado.']],case='Dos personas desean cosas distintas: una busca una relación estable y otra encuentros ocasionales. Al conversar lo reconocen y deciden no continuar. La claridad evita sostener un vínculo esperando que el otro cambie para ajustarse a un deseo que nunca compartió.',opportunities=[['Autoconocimiento','Nombrar expectativas antes de comprometerte.'],['Comunicación','Preguntar en lugar de deducir acuerdos.'],['Elección','Aceptar incompatibilidades sin descalificar a la otra persona.']],exercise=['Lo que deseo y lo que ofrezco','Escribe tus expectativas, límites y compromisos posibles. Señala qué temas necesitan conversación mutua.'],plan=['Identificar expectativas','Definir límites propios','Revisar tiempo disponible','Preparar preguntas claras','Conversar acuerdos','Observar su cumplimiento','Decidir con la información disponible'],questions=['¿Hemos expresado expectativas compatibles?','¿Ambos podemos elegir libremente?','¿Estoy esperando un cambio que nunca se acordó?'],principle='La intimidad se elige con libertad y se cuida mediante acuerdos claros.'),
13: dict(title='Evaluar consistencia sin convertirla en sospecha permanente',purpose='Construir confianza mediante observación de conductas y conversaciones directas.',deepening=['La consistencia entre palabras y actos es el centro del capítulo. Puedes observar cumplimiento, respuesta ante un desacuerdo y disposición a reparar un error. Un episodio proporciona información; un patrón requiere tiempo y contexto. Evita convertir una impresión inicial en una conclusión definitiva.','La evaluación silenciosa no necesita trampas ni vigilancia. Comunica los acuerdos importantes y permite que la otra persona también conozca tus expectativas. La confianza se construye de forma gradual y admite reconocer límites de información. Evalúa a cada persona por su conducta particular.'],method=[['Definir el acuerdo','Aclara qué se espera y qué condiciones pueden afectar el cumplimiento.'],['Observar varias situaciones','Registra cumplimiento y contexto en lugar de solo buscar fallas.'],['Conversar una discrepancia','Pregunta por lo ocurrido y observa cómo se resuelve.']],case='Un colaborador entrega tarde una tarea y avisa de un problema concreto. En las siguientes entregas cumple el plazo y mantiene informado al equipo. La evaluación incorpora el error y la reparación, en lugar de usar un episodio para definir toda su confiabilidad.',opportunities=[['Criterio','Diferenciar hechos, interpretación y datos faltantes.'],['Acuerdos','Hacer explícitas tus expectativas.'],['Confianza','Reconocer cumplimiento y reparación a lo largo del tiempo.']],exercise=['Hecho e interpretación','Describe un episodio en dos columnas: lo que observaste y lo que inferiste. Añade una pregunta que aclare el contexto.'],plan=['Elegir un acuerdo','Definir expectativas','Observar su cumplimiento','Separar hecho e interpretación','Conversar una discrepancia','Revisar la respuesta','Actualizar tu evaluación'],questions=['¿Qué observé directamente?','¿Qué explicación aún no he preguntado?','¿Reconozco los actos consistentes además de las fallas?'],principle='La confianza madura con información, acuerdos y consistencia observada.'),
14: dict(title='Respeto y presencia: observar lo que puedes practicar',purpose='Desarrollar una presencia coherente a través de preparación, límites y trato recíproco.',deepening=['La bioquímica del respeto es una imagen fuerte para hablar de presencia. En esta ampliación, la llevamos a aspectos practicables: preparación, claridad al hablar, puntualidad y capacidad de escuchar. Puedes revisar esas conductas sin intentar adivinar una condición biológica a partir de la impresión que produce alguien.','El lenguaje endocrino de la obra no constituye una medición del respeto. Distingue la interpretación literaria de una afirmación científica. La consideración de otras personas también depende del contexto y de sus decisiones; tu ámbito de trabajo es la conducta que puedes sostener con coherencia.'],method=[['Prepararte','Conoce el asunto y los datos necesarios antes de una interacción.'],['Cuidar la claridad','Expresa una idea por vez y permite que la otra persona responda.'],['Cumplir','Respeta el acuerdo que alcanzaste y comunica cualquier cambio.']],case='Una persona dirige por primera vez una reunión. Lleva una agenda breve, escucha objeciones y deja responsables y fechas. Aunque su voz es tranquila, el equipo reconoce una coordinación clara porque cada intervención ayuda a resolver el trabajo.',opportunities=[['Preparación','Llegar con información relevante.'],['Presencia','Participar con atención y sin prisa por impresionar.'],['Cumplimiento','Respaldar tus palabras después de la conversación.']],exercise=['Una presencia observable','Elige tres conductas que quieras practicar en tu próxima reunión y evalúalas al terminar.'],plan=['Elegir una interacción','Preparar información','Definir una petición','Ensayar una explicación breve','Practicar escucha','Cumplir el acuerdo','Revisar las tres conductas'],questions=['¿Qué conducta concreta quiero mejorar?','¿Qué aporté a la interacción?','¿Cumplí lo que dije que haría?'],principle='La presencia gana consistencia cuando tu preparación, palabra y conducta coinciden.'),
15: dict(title='Hábitos y energía: separar observación y explicación',purpose='Revisar tu funcionamiento cotidiano sin deducir estados hormonales de rasgos de personalidad.',deepening=['El capítulo relaciona energía, hábitos y masculinidad mediante afirmaciones hormonales. Esta ampliación trabaja con lo que puedes describir: horarios, actividades, carga de trabajo y continuidad de tus tareas. Sentirte cansado o dudar en una conversación no permite establecer por sí solo una alteración hormonal.','Una imagen literaria y una explicación clínica cumplen funciones diferentes. Registra el problema concreto antes de atribuirlo a una causa. El objetivo editorial es organizar hábitos y preguntas; no interpretar pruebas ni proponer tratamientos hormonales. Evalúa cambios cotidianos mediante resultados observables.'],method=[['Describir el problema','Anota cuándo aparece la dificultad y qué actividad interrumpe.'],['Revisar el contexto','Observa horarios, carga y cambios recientes sin asumir una única causa.'],['Hacer un ajuste','Modifica una condición organizativa y registra lo que ocurre.']],case='Un estudiante siente que rinde poco y lo interpreta como falta de carácter. Su registro muestra sesiones nocturnas después de jornadas extensas. Reorganiza la tarea más exigente a una franja disponible de la mañana y compara cuántos problemas resuelve.',opportunities=[['Observación','Describir dificultades antes de explicarlas.'],['Organización','Ajustar la carga a tu disponibilidad real.'],['Criterio','Distinguir una hipótesis de una conclusión.']],exercise=['Registro de funcionamiento','Durante siete días anota horarios, tarea principal y resultado. Busca un patrón concreto, sin asignarte etiquetas.'],plan=['Describir la dificultad','Registrar horarios','Registrar carga de tareas','Elegir un ajuste','Probarlo','Comparar el desempeño','Preparar preguntas aún abiertas'],questions=['¿Qué estoy observando realmente?','¿Qué causa estoy suponiendo sin datos?','¿Qué ajuste produjo un cambio verificable?'],principle='Describir con precisión abre más posibilidades que explicarlo todo con una etiqueta.'),
16: dict(title='Legado familiar: presencia, acuerdos y ejemplo',purpose='Pensar la crianza como una responsabilidad compartida y continuada.',deepening=['El legado del capítulo puede trasladarse a la forma de acompañar el desarrollo de un hijo: tiempo, ejemplo, cuidado y acuerdos entre responsables. Pregúntate qué valores se ven en tus actos y qué condiciones permiten al niño aprender, preguntar y desarrollar su propio criterio.','Las metáforas de selección e ingeniería no determinan el valor de una persona ni permiten diseñar su futuro. Cada hijo desarrolla intereses y decisiones propios. Un proyecto de crianza requiere reconocer esa individualidad y conversar responsabilidades, recursos y diferencias entre los adultos.'],method=[['Definir valores mediante actos','Elige ejemplos cotidianos de responsabilidad, respeto y honestidad.'],['Conversar responsabilidades','Acuerda tareas, disponibilidad y criterios de cuidado con quienes participan.'],['Revisar el ejemplo','Observa si tus actos enseñan lo que dices valorar.']],case='Dos adultos quieren enseñar constancia, pero discuten sus obligaciones sin acuerdos. Distribuyen tareas, cumplen horarios de cuidado y reconocen cuando se equivocan. El niño puede observar el valor en acciones repetidas y no únicamente en instrucciones.',opportunities=[['Coherencia','Enseñar mediante conductas cotidianas.'],['Acuerdos','Distribuir responsabilidades de forma explícita.'],['Autonomía','Escuchar intereses y preguntas de los hijos.']],exercise=['Un valor visible','Elige un valor familiar y describe una acción que lo muestre. Señala quién la sostendrá y cómo se revisará.'],plan=['Nombrar valores','Describir acciones cotidianas','Revisar responsabilidades','Conversar un acuerdo','Cumplir una tarea de cuidado','Escuchar una necesidad','Revisar el ejemplo ofrecido'],questions=['¿Qué enseñan mis actos?','¿Qué responsabilidad necesito acordar mejor?','¿Estoy dejando espacio para la individualidad de mi hijo?'],principle='El legado familiar se construye con presencia, responsabilidad y ejemplo.'),
17: dict(title='Cuidar sin perder tus límites',purpose='Distinguir apoyo posible, acuerdos compartidos y cargas que exceden tu capacidad.',deepening=['El capítulo presenta el desgaste de sostener un vínculo donde las necesidades parecen interminables. Para examinarlo, describe qué apoyo se pide, con qué frecuencia y qué efecto tiene en tu vida. La vulnerabilidad de alguien no resume su valor ni demuestra que el cuidado sea inútil.','Un apoyo sostenible tiene alcance y participación. Puedes acompañar una situación y reconocer que no puedes asumir todas sus consecuencias. Conversa lo que ofreces, lo que necesitas preservar y qué otras personas o recursos pueden participar. Evalúa el vínculo por conductas individuales y acuerdos.'],method=[['Definir el apoyo','Especifica tiempo, tarea y recursos que puedes aportar.'],['Comunicar la capacidad','Explica con claridad qué parte excede tus posibilidades.'],['Revisar reciprocidad','Observa si se respetan límites y acuerdos.']],case='Una persona recibe llamadas extensas cada noche y empieza a incumplir sus tareas. Propone conversar dos veces por semana en un horario acordado y aclara que no puede estar disponible continuamente. El apoyo se vuelve concreto y su agenda recupera espacio.',opportunities=[['Límites','Ofrecer ayuda dentro de una capacidad real.'],['Redes','Reconocer que una necesidad puede requerir más apoyos.'],['Reciprocidad','Examinar cómo se respetan los acuerdos.']],exercise=['Capacidad de apoyo','Escribe qué puedes ofrecer, con qué frecuencia y qué obligación debes conservar. Prepara una conversación breve.'],plan=['Describir la petición habitual','Medir el tiempo dedicado','Definir tu capacidad','Proponer un acuerdo','Comunicarlo','Observar su cumplimiento','Revisar el equilibrio del apoyo'],questions=['¿Qué apoyo estoy ofreciendo realmente?','¿Qué límite necesito expresar?','¿Se respetan mis obligaciones y la libertad del otro?'],principle='El cuidado se sostiene mejor cuando tiene acuerdos y límites claros.'),
18: dict(title='Historia personal y compatibilidad presente',purpose='Evaluar un vínculo por conductas actuales y acuerdos, sin convertir el pasado en una sentencia.',deepening=['El pasado de una persona puede importar para comprender expectativas y experiencias. La decisión sobre un vínculo necesita información pertinente, disposición a conversar y observación del presente. Puedes reconocer incompatibilidades sin deducir que una historia vuelve a alguien incapaz de construir una relación.','Las imágenes genéticas del ensayo no permiten concluir alteraciones biológicas a partir de relaciones previas. En este desarrollo, la evaluación se centra en honestidad, acuerdos y conducta actual. Cada persona conserva su privacidad; solo comparte lo que desea y lo que resulta relevante para decisiones mutuas.'],method=[['Definir lo relevante','Identifica qué información necesitas para decidir y por qué.'],['Conversar sin interrogar','Pregunta por expectativas y acuerdos respetando la privacidad.'],['Evaluar el presente','Observa conductas consistentes con lo que ambos han expresado.']],case='Alguien teme comenzar una relación con una persona que tuvo una separación difícil. En lugar de asignarle un destino por su historia, conversa expectativas y observa cómo ambos resuelven diferencias. Puede decidir continuar o retirarse usando información presente y compatibilidad.',opportunities=[['Criterio','Distinguir contexto histórico y conducta actual.'],['Respeto','Mantener privacidad y libertad al conversar.'],['Elección','Decidir sin descalificar la historia ajena.']],exercise=['Mi criterio de compatibilidad','Escribe tres conductas presentes que necesitas en un vínculo y cómo reconocerías su cumplimiento.'],plan=['Identificar un temor','Separar hechos y suposiciones','Definir información pertinente','Preparar preguntas respetuosas','Conversar expectativas','Observar acuerdos presentes','Revisar tu decisión'],questions=['¿Qué sé y qué estoy suponiendo?','¿Esta información es pertinente para un acuerdo actual?','¿Qué conducta presente sostiene mi evaluación?'],principle='La compatibilidad se examina con información pertinente y conducta presente.'),
19: dict(title='Desvincularse y ordenar la vida digital',purpose='Cerrar una relación o colaboración y reorganizar tus canales de contacto.',deepening=['La limpieza de huella del capítulo puede aplicarse a recordatorios, notificaciones y accesos compartidos que mantienen abierta una etapa. Define qué comunicación seguirá siendo necesaria y qué canales dejarás de usar. Ordenar tu entorno digital evita que cada aviso reactive un asunto que ya decidiste cerrar.','Conserva documentos que necesitas y respeta archivos y cuentas ajenas. Si existen compromisos, deja un canal adecuado para resolverlos. La finalidad de esta práctica es organizar tu participación y privacidad, sin vigilancia, suplantación ni acciones sobre recursos que no te pertenecen.'],method=[['Inventariar canales','Lista chats, carpetas y servicios donde tienes participación.'],['Cerrar responsabilidades','Devuelve archivos o recursos y acuerda el canal para pendientes.'],['Ordenar tus accesos','Ajusta tus notificaciones y permisos sobre cuentas propias.']],case='Después de salir de un proyecto, un integrante recibe alertas de cinco grupos. Entrega sus documentos, confirma que otro responsable recibió el trabajo y abandona los grupos operativos. Conserva el registro de entregas y un correo para resolver asuntos administrativos.',opportunities=[['Privacidad','Revisar tus propios accesos y permisos.'],['Concentración','Eliminar avisos que ya no requieren tu acción.'],['Orden','Conservar un registro de pendientes y entregas.']],exercise=['Mapa de canales','Clasifica tus canales en necesarios, pendientes de cierre y prescindibles. Realiza una acción en la última categoría.'],plan=['Inventariar canales','Identificar pendientes','Respaldar documentos propios necesarios','Completar una entrega','Cerrar un canal prescindible','Revisar permisos propios','Confirmar el cierre práctico'],questions=['¿Qué canal todavía necesito?','¿Qué responsabilidad continúa pendiente?','¿Estoy organizando mi privacidad respetando recursos ajenos?'],principle='El cierre digital funciona cuando coincide con un cierre práctico de responsabilidades.'),
20: dict(title='Atención e intimidad: decisiones deliberadas',purpose='Organizar hábitos y elecciones íntimas de acuerdo con tus prioridades y acuerdos.',deepening=['La energía sexual del capítulo puede leerse como una metáfora de atención y elección. En esta ampliación se observa cuánto tiempo dedicas a ciertos estímulos y si tus hábitos coinciden con lo que deseas. La decisión de participar o abstenerte pertenece a tu autonomía y debe respetar la de otras personas.','La retórica sobre pérdida de núcleo o energía no demuestra que una eyaculación reduzca liderazgo o valor personal. No se propone una intervención hormonal. El ejercicio editorial consiste en reconocer hábitos, crear límites de tiempo y sostener expectativas claras, sin convertir la sexualidad en una medida de dignidad.'],method=[['Observar el hábito','Registra estímulo, tiempo dedicado y tarea desplazada.'],['Elegir un límite','Decide un horario o una condición que proteja una prioridad.'],['Revisar acuerdos','Comprueba que las decisiones íntimas respeten libertad y expectativas mutuas.']],case='Una persona pasa largos periodos conversando de madrugada y posterga sus proyectos. Decide cerrar mensajes a una hora acordada y reservar el primer bloque disponible para trabajar. Evalúa el cambio por tiempo recuperado y tareas cumplidas.',opportunities=[['Atención','Reconocer qué estímulos desplazan prioridades.'],['Autonomía','Elegir hábitos sin convertirlos en una obligación universal.'],['Acuerdos','Comunicar disponibilidad y expectativas.']],exercise=['Tiempo y elección','Describe un hábito y elige un ajuste que puedas probar. Define qué resultado observarás al terminar la semana.'],plan=['Registrar el hábito','Medir tiempo y contexto','Elegir una prioridad','Definir un límite horario','Probar el ajuste','Conversar disponibilidad','Comparar tiempo y tareas'],questions=['¿Qué hábito deseo cambiar y por qué?','¿Cómo respeta mi decisión la libertad ajena?','¿Qué resultado concreto evaluaré?'],principle='La elección deliberada se reconoce en hábitos y acuerdos que puedes sostener.'),
21: dict(title='Comunicación no verbal y palabras necesarias',purpose='Alinear tu presencia, escucha y mensajes sin depender de que otros adivinen tus intenciones.',deepening=['El silencio y la presencia tienen un papel central en el capítulo. Una pausa puede darte tiempo para escuchar y organizar una respuesta. Postura, ritmo y atención forman parte de una interacción, pero su significado varía con el contexto; no ofrecen una traducción única de lo que alguien piensa.','Cuando hay acuerdos o límites en juego, exprésalos con palabras. La coherencia comunicativa combina lo que dices con cómo actúas. Evita usar el silencio para exigir que otra persona deduzca una decisión que nunca se ha comunicado.'],method=[['Observar tu participación','Reconoce si interrumpes, miras el teléfono o respondes sin escuchar.'],['Hacer una pausa','Permite que la otra persona termine y resume lo que entendiste.'],['Expresar lo necesario','Di la decisión o petición con claridad y confirma el acuerdo.']],case='En una conversación tensa, alguien deja de interrumpir y espera a que termine la explicación. Resume el problema y expresa una propuesta. Su pausa facilita la escucha; sus palabras permiten acordar un siguiente paso sin obligar al otro a interpretar gestos.',opportunities=[['Escucha','Dar espacio a información que cambia tu evaluación.'],['Presencia','Reducir distracciones durante una interacción.'],['Claridad','Comunicar decisiones que requieren acuerdo.']],exercise=['Pausa y resumen','En una conversación cotidiana, escucha hasta el final y resume el mensaje antes de responder.'],plan=['Observar una conversación','Identificar una interrupción habitual','Preparar una pregunta','Practicar una pausa','Resumir lo entendido','Expresar una petición','Revisar la claridad del acuerdo'],questions=['¿Estoy escuchando o esperando mi turno?','¿Qué significado estoy atribuyendo sin preguntar?','¿Qué necesita decirse explícitamente?'],principle='El silencio facilita la escucha; las palabras claras permiten construir acuerdos.'),
22: dict(title='Etapas de formación como mapa de prácticas',purpose='Convertir las etapas del ensayo en un recorrido revisable de aprendizaje personal.',deepening=['El capítulo presenta cuatro etapas mediante imágenes de ruptura y reconstrucción. Puedes emplearlas como un mapa narrativo para reconocer una dificultad, revisar hábitos, practicar decisiones y sostener un criterio. No necesitas reducir tu identidad a una etapa ni comparar tu valor con el de otro lector.','El cambio suele requerir volver sobre problemas conocidos y ajustar herramientas. Define qué práctica corresponde a tu momento y qué resultado demostraría avance. El mapa adquiere utilidad cuando te ayuda a elegir una acción, en lugar de limitarse a nombrar cómo te sientes.'],method=[['Ubicar una dificultad','Describe una conducta que quieres revisar.'],['Elegir una práctica','Selecciona una acción adecuada a esa dificultad.'],['Evaluar continuidad','Observa su repetición y ajusta lo que impide sostenerla.']],case='Un lector se identifica con la etapa de ruptura, pero no sabe cómo avanzar. Elige trabajar un límite horario, lo comunica y lo prueba durante una semana. Su avance se expresa en una conducta concreta y no solo en adoptar el nombre de otra etapa.',opportunities=[['Autoconocimiento','Nombrar una dificultad sin convertirla en identidad fija.'],['Práctica','Elegir un cambio manejable.'],['Evaluación','Reconocer avances parciales y ajustes pendientes.']],exercise=['Mi siguiente práctica','Escribe una dificultad, una acción repetible y una señal de avance que puedas observar.'],plan=['Leer las etapas','Nombrar una dificultad','Elegir una acción','Preparar sus condiciones','Practicarla','Repetir y ajustar','Evaluar el siguiente paso'],questions=['¿Qué acción corresponde a mi momento actual?','¿Qué cambio puedo observar?','¿Qué necesito repetir antes de aumentar la exigencia?'],principle='Un mapa de formación sirve cuando orienta tu siguiente práctica.'),
23: dict(title='Criterio propio frente a la búsqueda de aprobación',purpose='Tomar decisiones con razones propias y escuchar opiniones sin depender de ellas.',deepening=['El capítulo se centra en buscar validación en las relaciones. Puedes ampliar esa reflexión a cualquier situación donde cambias una decisión únicamente para ser aceptado. Identifica qué esperas conseguir y qué prioridad estás dejando de atender. Esa observación permite recuperar participación consciente en tus elecciones.','La cortesía y la empatía pueden ser elecciones libres y coherentes. El problema práctico aparece cuando dices algo que no sostienes o aceptas una obligación que no puedes cumplir por temor al desacuerdo. Escuchar una opinión aporta información; conservar criterio implica evaluar sus razones.'],method=[['Reconocer el incentivo','Pregunta qué aprobación buscas antes de decidir.'],['Escribir tus razones','Define por qué una opción responde a tus valores y capacidades.'],['Escuchar y elegir','Considera observaciones útiles y toma responsabilidad por la conclusión.']],case='Alguien acepta una actividad costosa para impresionar a una persona. Al revisar sus razones, ve que compromete una meta de ahorro. Propone otra actividad que sí puede sostener y acepta que la respuesta ajena no depende de él.',opportunities=[['Autonomía','Elegir compromisos dentro de tus posibilidades.'],['Relaciones','Mantener respeto sin prometer para agradar.'],['Criterio','Escuchar razones y distinguirlas de la presión.']],exercise=['Decisión sin público','Elige una decisión reciente y escribe qué harías si nadie fuera a conocerla. Compara tus motivos.'],plan=['Identificar una búsqueda de aprobación','Describir la decisión','Escribir razones propias','Revisar recursos disponibles','Escuchar una opinión concreta','Elegir y comunicar','Evaluar coherencia y consecuencias'],questions=['¿Qué aprobación estoy buscando?','¿Qué razón mantendría sin un observador?','¿Puedo sostener lo que estoy ofreciendo?'],principle='El criterio propio permite relacionarte sin entregar a otros toda tu decisión.'),
24: dict(title='Construir un legado antes de exhibirlo',purpose='Priorizar trabajo terminado y documentación útil sobre reconocimiento inmediato.',deepening=['El ascenso sin testigos del capítulo invita a trabajar cuando no existe recompensa pública. Para aplicarlo, elige una obra que merezca continuidad y define qué resultado quieres dejar. Un proyecto pequeño terminado puede aportar más aprendizaje que una declaración ambiciosa sin ejecución.','La privacidad del proceso puede proteger la concentración. Compartir resultados en el momento adecuado también permite recibir revisión y facilitar su uso. Define cuándo comunicarás avances y a quién le serán útiles. El legado requiere que lo construido pueda conservarse y comprenderse.'],method=[['Definir una entrega','Elige un resultado limitado que puedas completar.'],['Trabajar con continuidad','Reserva bloques y registra decisiones sin publicar cada paso.'],['Dejarlo utilizable','Ordena archivos, instrucciones y una explicación del propósito.']],case='Un integrante prepara una guía durante cuatro semanas sin anunciarla cada día. Al terminar, pide revisión a dos personas, corrige errores y publica una versión ordenada. El trabajo adquiere valor porque puede usarse y actualizarse.',opportunities=[['Concentración','Reducir la necesidad de mostrar cada avance.'],['Calidad','Solicitar revisión cuando exista una muestra útil.'],['Legado','Documentar para que el resultado continúe.']],exercise=['Una entrega de legado','Define un producto, quién lo usará y cómo sabrás que está listo.'],plan=['Definir la entrega','Elegir destinatarios','Ordenar materiales','Producir una sección','Completar el borrador','Solicitar revisión concreta','Guardar una versión utilizable'],questions=['¿Qué resultado estoy construyendo?','¿Quién podrá usarlo?','¿Qué documentación necesita para continuar?'],principle='El legado empieza en un trabajo que otras personas pueden comprender y usar.'),
25: dict(title='Revisar lo aprendido y elegir tu conducta',purpose='Examinar reglas heredadas y conservar las que responden a tus valores actuales.',deepening=['La desactivación del capítulo expresa una revisión de expectativas aprendidas. Para llevarla a la práctica, identifica una regla que sigues sin haberla examinado: evitar desacuerdos, aceptar cualquier petición o medir tu valor por una reacción ajena. Describe cuándo apareció y qué efecto tiene hoy.','Una regla aprendida puede ser útil, necesitar ajustes o dejar de servir. La revisión no obliga a rechazar la educación, la sensibilidad o la cooperación. Consiste en elegir una conducta con razones propias y asumir sus consecuencias, considerando la libertad y las responsabilidades de otras personas.'],method=[['Nombrar una regla','Escribe lo que sientes que siempre debes hacer.'],['Examinar su función','Identifica qué protegía y qué coste tiene en tu contexto actual.'],['Elegir una alternativa','Formula una regla más precisa y pruébala en una situación manejable.']],case='Una persona aprendió que nunca debe contradecir a un superior. En un proyecto detecta un error y prepara una observación con datos y una alternativa. Mantiene el respeto y decide participar con criterio, en lugar de guardar silencio por costumbre.',opportunities=[['Autoconocimiento','Reconocer expectativas que sigues automáticamente.'],['Participación','Expresar desacuerdos con información.'],['Responsabilidad','Elegir conductas y revisar sus efectos.']],exercise=['Una regla revisada','Completa: antes asumía que debía; ahora elegiré; lo probaré en; revisaré este resultado.'],plan=['Identificar una regla','Recordar su origen','Examinar su utilidad','Escribir una alternativa','Ensayarla','Probarla en una situación','Revisar efectos y ajustes'],questions=['¿Esta regla sirve a mis valores actuales?','¿Qué alternativa respeta mis responsabilidades?','¿Qué consecuencia estoy dispuesto a asumir?'],principle='Revisar lo aprendido permite elegir cómo participar en tu vida actual.'),
26: dict(title='Recibir un rechazo y conservar dirección',purpose='Responder a una negativa sin convertirla en una conclusión sobre todo tu valor.',deepening=['La inmunidad al rechazo del ensayo expresa independencia frente a la elección ajena. En la práctica puedes reconocer la decepción, aceptar la negativa y distinguir lo que te informa de lo que no demuestra. Un rechazo puede reflejar preferencias, criterios o circunstancias que no controlas.','Cuando exista una evaluación útil, puedes aprender de ella. Cuando se trate de una decisión personal, respeta el límite y evita insistir para cambiarlo. Tu siguiente acción puede consistir en mejorar una habilidad, presentar otra propuesta o cerrar la búsqueda en ese contexto.'],method=[['Aceptar la respuesta','Identifica la negativa y deja de tratarla como un acuerdo pendiente.'],['Separar ámbitos','Distingue un aspecto mejorable de una preferencia que corresponde a otro.'],['Elegir continuidad','Define una acción compatible con tus valores y con el límite recibido.']],case='Un aspirante no consigue una plaza. Solicita una observación concreta, descubre un aspecto técnico que necesita mejorar y diseña una práctica. En una relación personal, una negativa no se transforma en un plan de insistencia: se respeta la decisión.',opportunities=[['Aprendizaje','Usar una evaluación específica cuando esté disponible.'],['Límites','Respetar negativas personales.'],['Continuidad','Elegir una siguiente acción dentro de tu control.']],exercise=['Respuesta y siguiente paso','Escribe qué respuesta recibiste, qué información aporta y qué acción depende de ti.'],plan=['Describir la negativa','Reconocer tu reacción','Separar información y juicio global','Revisar un aspecto mejorable','Diseñar una práctica','Realizar el primer paso','Evaluar tu continuidad'],questions=['¿Qué demuestra esta respuesta y qué no?','¿Qué puedo aprender sin insistir sobre un límite?','¿Qué siguiente paso depende de mí?'],principle='Una negativa puede cerrar una opción sin cerrar tu capacidad de continuar.'),
27: dict(title='Bajo perfil con propósito y visibilidad suficiente',purpose='Elegir qué compartir, con quién y en qué momento según la finalidad de tu trabajo.',deepening=['El bajo perfil del capítulo propone conservar atención y libertad frente a la exposición constante. Para aplicarlo, distingue trabajo privado, información que necesita tu equipo y resultados que conviene mostrar. La elección depende de la función que cumple cada comunicación.','Una privacidad deliberada puede convivir con visibilidad profesional suficiente. Si nadie conoce tu disponibilidad o capacidad, algunas oportunidades no podrán encontrarte. Comparte pruebas pertinentes sin convertir cada actividad en una exhibición. Reconoce qué parte de tu proceso deseas reservar y cuál necesita colaboración.'],method=[['Clasificar información','Separa proceso privado, coordinación necesaria y resultados compartibles.'],['Elegir destinatarios','Define quién necesita cada información para actuar.'],['Mostrar una prueba','Presenta un resultado terminado y explica su utilidad.']],case='Una persona evita publicar cada jornada de trabajo, pero conserva un portafolio actualizado. Su equipo recibe reportes breves y quienes buscan colaboradores pueden ver muestras reales. El bajo perfil protege su proceso y mantiene abiertos los canales necesarios.',opportunities=[['Privacidad','Decidir conscientemente qué reservar.'],['Coordinación','Informar a quienes dependen de tu trabajo.'],['Oportunidades','Mostrar resultados verificables.']],exercise=['Mapa de visibilidad','Clasifica cinco datos o avances de tu proyecto y define destinatario y momento de comunicación.'],plan=['Listar información del proyecto','Clasificar su función','Elegir destinatarios','Preparar una muestra','Comunicar un avance necesario','Reservar un proceso privado','Revisar oportunidades y coordinación'],questions=['¿Para qué compartiría esta información?','¿Quién la necesita realmente?','¿Mi privacidad dificulta algún compromiso de coordinación?'],principle='El bajo perfil funciona cuando eliges la visibilidad que sirve a tu propósito.'),
28: dict(title='Territorio interno: observar pensamientos y elegir acciones',purpose='Reconocer patrones de respuesta y trabajar un cambio concreto en tu conducta.',deepening=['El territorio interno de la obra reúne pensamientos, emociones y hábitos. Para explorarlo, describe una situación, la interpretación que aparece y la acción posterior. Separar esos elementos permite reconocer que una interpretación es una respuesta posible y que puedes examinarla antes de actuar.','Este mapa es una herramienta de reflexión editorial. No constituye un diagnóstico ni permite dominar literalmente el sistema nervioso. La práctica consiste en identificar qué está bajo tu control, hacer una pausa y elegir un paso proporcionado a la situación.'],method=[['Registrar la secuencia','Escribe situación, pensamiento, emoción y conducta.'],['Examinar la interpretación','Pregunta qué datos la apoyan y qué información falta.'],['Elegir un paso','Realiza una acción pequeña que responda al problema observable.']],case='Un estudiante recibe una corrección y piensa que todo su trabajo es inútil. Revisa el comentario y descubre que se refiere a una tabla. Corrige esa parte y pide aclaración sobre un dato. La acción responde a lo señalado, en lugar de a una conclusión global.',opportunities=[['Observación','Reconocer tu secuencia habitual de respuesta.'],['Criterio','Examinar interpretaciones antes de actuar.'],['Acción','Resolver una parte concreta del problema.']],exercise=['Secuencia de una situación','Registra un episodio reciente y escribe otra interpretación compatible con los hechos. Define una acción útil.'],plan=['Elegir un episodio','Registrar la secuencia','Separar hechos y pensamientos','Buscar información faltante','Elegir un paso pequeño','Realizarlo','Revisar su efecto'],questions=['¿Qué ocurrió de forma observable?','¿Qué interpretación añadí?','¿Qué acción puede resolver una parte real del problema?'],principle='Reconocer tu respuesta abre espacio para elegir una acción más precisa.'),
29: dict(title='Canalizar el deseo hacia decisiones sostenibles',purpose='Reconocer impulsos y organizar acciones compatibles con tus prioridades y la libertad ajena.',deepening=['El deseo mal canalizado del capítulo puede analizarse como una secuencia de estímulo, impulso y acción. Sentir atracción no determina qué harás después. Puedes observar cuánto tiempo dedica tu conducta a perseguir estímulos y qué actividades estás desplazando.','La dirección personal incluye consentimiento y aceptación de límites. Un deseo propio no establece una obligación para otra persona. Decide qué hábitos quieres cultivar y prepara alternativas disponibles cuando aparezca un estímulo que suele desviar tu atención.'],method=[['Identificar la secuencia','Anota estímulo, impulso, acción y resultado.'],['Preparar una alternativa','Elige una tarea breve que puedas comenzar cuando quieras redirigir tu tiempo.'],['Respetar límites','Acepta negativas y evita convertir una búsqueda en insistencia.']],case='Alguien abre una aplicación cada vez que una tarea se vuelve difícil. Reconoce el patrón, cierra notificaciones durante su bloque y deja una lista de pasos pequeños para retomar el trabajo. La alternativa está preparada antes de que aparezca el impulso.',opportunities=[['Atención','Reconocer desvíos habituales.'],['Entorno','Preparar alternativas accesibles.'],['Relaciones','Elegir conductas que respeten decisiones ajenas.']],exercise=['Un desvío frecuente','Dibuja por escrito la secuencia de un hábito. Inserta una alternativa concreta entre impulso y acción.'],plan=['Registrar un desvío','Identificar el estímulo','Elegir una prioridad','Preparar una alternativa','Modificar el entorno','Probar la nueva secuencia','Revisar tiempo y resultados'],questions=['¿Qué conducta sigue habitualmente a mi impulso?','¿Qué alternativa tengo preparada?','¿Mi acción respeta límites y acuerdos?'],principle='Puedes reconocer un deseo y decidir qué lugar tendrá en tu conducta.'),
30: dict(title='Responsabilidad adulta y cuidado de tu historia',purpose='Reconocer necesidades antiguas sin dejar que decidan automáticamente tu conducta actual.',deepening=['El niño emocional interno funciona como una figura narrativa de necesidades y respuestas aprendidas. Puedes usarla para reconocer cuándo buscas confirmación, evitas un desacuerdo o entregas más de lo que puedes sostener. Describir la situación ayuda a trabajar una decisión presente.','La madurez admite afecto, vulnerabilidad y apoyo. Este desarrollo propone asumir responsabilidad por tus acciones y expresar necesidades de forma clara. Comprender tu historia no exige castigarte por haber necesitado cuidado ni actuar como si debieras resolver todo sin compañía.'],method=[['Reconocer una necesidad','Nombra qué esperabas recibir en una situación reciente.'],['Separar tiempos','Distingue lo que recuerda esa experiencia de lo que ocurre ahora.'],['Actuar como responsable','Expresa una petición o límite y acepta la libertad de respuesta ajena.']],case='Una persona interpreta una demora en mensajes como abandono y envía reclamaciones. Antes de repetirlo, reconoce su deseo de confirmación y conversa expectativas de comunicación. Acuerdan horarios posibles y cada uno conserva sus obligaciones.',opportunities=[['Autoconocimiento','Nombrar necesidades sin convertirlas en vergüenza.'],['Comunicación','Expresar peticiones proporcionadas.'],['Responsabilidad','Elegir respuestas que respeten la autonomía de ambos.']],exercise=['Necesidad y petición','Escribe una necesidad, la reacción habitual y una petición concreta que podrías comunicar.'],plan=['Recordar una situación','Nombrar la necesidad','Describir la reacción','Separar pasado y presente','Preparar una petición','Conversarla','Revisar la respuesta elegida'],questions=['¿Qué necesidad estoy intentando resolver?','¿Mi reacción corresponde a la situación actual?','¿Qué petición puedo expresar sin exigir una respuesta?'],principle='La responsabilidad adulta permite reconocer necesidades y elegir cómo actuar.'),
31: dict(title='Soledad elegida y regreso con autonomía',purpose='Practicar decisiones propias durante un espacio delimitado de reflexión.',deepening=['La soledad como autoridad se entiende aquí como capacidad de dirigir tu participación. Puedes usar un tiempo a solas para elegir una prioridad sin consultar cada detalle. El ejercicio no elimina la posibilidad de pedir información o apoyo cuando los necesitas.','La autoridad sobre tu agenda se demuestra en decisiones que sostienes al regresar. Define qué actividad harás, cuánto durará y qué resultado esperas. Una autonomía útil te permite relacionarte por elección y cumplir con los vínculos que deseas conservar.'],method=[['Elegir una decisión propia','Selecciona un asunto que puedas resolver con información suficiente.'],['Trabajar en un tiempo delimitado','Reserva un bloque y evita consultar por inercia.'],['Volver y ejecutar','Comunica lo necesario y realiza el paso elegido.']],case='Una persona consulta a varias amistades cada decisión de estudio y termina confundida. Reserva una hora, compara fechas y escoge un plan. Pide información solo sobre un requisito que desconoce y empieza la primera tarea ese mismo día.',opportunities=[['Decisiones','Reducir consultas que repiten la misma incertidumbre.'],['Información','Distinguir pedir datos de pedir aprobación.'],['Participación','Regresar con un plan comunicable.']],exercise=['Una decisión de principio a fin','Escribe opciones, criterio y decisión. Realiza un primer paso antes de buscar confirmación adicional.'],plan=['Elegir el asunto','Reunir datos necesarios','Definir el criterio','Reservar un bloque propio','Tomar la decisión','Ejecutar el primer paso','Revisar autonomía y compromisos'],questions=['¿Qué información me falta realmente?','¿Estoy buscando datos o permiso emocional?','¿Qué acción confirma mi decisión?'],principle='La autonomía se fortalece cuando decides con criterio y vuelves para actuar.'),
32: dict(title='Atracción y criterio: evaluar sin idealizar',purpose='Reconocer afinidades sin asumir que garantizan compatibilidad o intenciones.',deepening=['El capítulo describe una atracción basada en afinidades que parecen especialmente convincentes. Para examinarla, distingue lo que admiras de lo que todavía desconoces. Compartir gustos, lenguaje o lecturas ofrece un punto de encuentro y no demuestra por sí solo cómo funcionará un vínculo.','Tampoco permite deducir manipulación a partir de una personalidad o de un sexo. Evalúa ritmo, respeto de límites y consistencia de acuerdos en cada persona. Puedes tomarte tiempo antes de ampliar un compromiso y preguntar directamente por expectativas.'],method=[['Separar afinidad y acuerdo','Escribe qué comparten y qué todavía necesitan conversar.'],['Mantener un ritmo propio','Conserva obligaciones y disponibilidad mientras conoces el vínculo.'],['Observar consistencia','Evalúa cómo responden ambos a diferencias y límites.']],case='Dos personas comparten libros y conversaciones intensas. Una propone pasar cada noche juntas; la otra necesita conservar su agenda. Conversan disponibilidad y observan si el acuerdo se respeta. La compatibilidad se comprueba en esa práctica cotidiana.',opportunities=[['Criterio','Reconocer lo conocido y lo pendiente.'],['Tiempo','Conocer un vínculo sin abandonar prioridades.'],['Acuerdos','Observar cómo se respetan límites concretos.']],exercise=['Afinidades y preguntas','Anota tres afinidades y tres asuntos sobre los que aún necesitas información. Prepara preguntas respetuosas.'],plan=['Listar afinidades','Identificar datos faltantes','Revisar disponibilidad propia','Conversar expectativas','Acordar un límite','Observar su cumplimiento','Actualizar tu evaluación'],questions=['¿Qué sé de esta persona además de nuestras afinidades?','¿Mi ritmo sigue siendo una elección propia?','¿Cómo respondemos a una diferencia concreta?'],principle='La afinidad abre una conversación; la compatibilidad se conoce en los acuerdos.'),
33: dict(title='Liderazgo que se demuestra en el trabajo',purpose='Evaluar liderazgo por responsabilidad, decisiones y resultados sostenidos.',deepening=['El capítulo cuestiona la distancia entre una imagen pública de liderazgo y la conducta real. Para examinarla, observa compromisos cumplidos, decisiones explicadas y capacidad de corregir un error. La apariencia puede llamar la atención, pero necesitas más información para evaluar una forma de dirigir.','El liderazgo propio comienza por ordenar lo que te corresponde. Cuando coordinas con otros, añade escucha, claridad y distribución de responsabilidades. Un resultado colectivo requiere que cada participante comprenda qué hará y tenga condiciones para cumplirlo.'],method=[['Definir responsabilidades','Aclara qué tarea te corresponde y qué necesita coordinación.'],['Tomar decisiones explicables','Presenta el criterio y admite información que obligue a corregir.'],['Revisar resultados','Comprueba entregas y reconoce tu parte en errores y avances.']],case='Un coordinador promete menos tareas de las que puede distribuir, acuerda responsables y revisa un obstáculo antes de la fecha de entrega. Cuando falla una estimación, la reconoce y reorganiza el trabajo. El equipo puede evaluar su liderazgo en la conducta sostenida.',opportunities=[['Confiabilidad','Cumplir compromisos y avisar cambios.'],['Coordinación','Dar claridad sobre tareas y criterios.'],['Aprendizaje','Corregir decisiones con responsabilidad.']],exercise=['Liderazgo observable','Elige un proyecto y define tres conductas que permitan evaluar tu participación: acuerdo, seguimiento y corrección.'],plan=['Elegir un proyecto','Definir responsabilidades','Acordar una entrega','Explicar un criterio','Revisar un obstáculo','Corregir una decisión necesaria','Evaluar trabajo y cumplimiento'],questions=['¿Qué responsabilidad asumí realmente?','¿Puedo explicar mi decisión?','¿Qué hice cuando apareció un error?'],principle='El liderazgo adquiere contenido cuando se demuestra en responsabilidad y trabajo sostenido.')
}

def build():
    assert set(SPECS)==set(range(1,34))
    results=json.loads(Path(__file__).with_name('results_masculino.json').read_text(encoding='utf-8'))
    for n,g in SPECS.items():
        assert len(g['deepening'])==2 and len(g['method'])==3
        assert len(g['plan'])==7 and len(g['questions'])==3
        assert len(results[str(n)])==7
        g['plan']=[[str(i+1),action,results[str(n)][i]] for i,action in enumerate(g['plan'])]
    out=Path(__file__).resolve().parents[1]/'wajomeismo-masculino/crecimiento.json'
    out.write_text(json.dumps(SPECS,ensure_ascii=False,indent=2),encoding='utf-8')
    print('Desarrollos:',len(SPECS))

if __name__=='__main__':build()
